SELECT *
FROM chat_message
WHERE conversation_id IN

    #{id}


    AND created_time > #{syncTime}

ORDER BY created_time ASC

SELECT *
FROM chat_message
WHERE conversation_id = #{conversationId}
  AND seq_id > #{anchorSeqId}
ORDER BY seq_id ASC
LIMIT #{limit}

SELECT *
FROM chat_message
WHERE conversation_id = #{conversationId}
  AND seq_id < #{anchorSeqId}
ORDER BY seq_id DESC
LIMIT #{limit}

SELECT *
FROM chat_message
WHERE conversation_id = #{conversationId}
  AND seq_id = #{seqId}
LIMIT 1
